13	)
14	
15	// backupSetup 构造一个覆盖全部状态的钱包：
16	//   - 账户 payer/u1/u2；会话 s1、s2（使用）、sa（出资审批）、s3（吊销）、
17	//     s4（已到期）；
18	//   - p-app 开审批（等待 5 分钟，预留超时 10 小时）、p-to 开预留超时
19	//     （1 分钟、无审批）、p-notime 不启用任何超时、p-deact 已停用；
20	//   - 请求覆盖直接预留、已结算、已预留后取消、待审批、已批准预留、被拒、
21	//     待审批取消、待审批过期、预留超时，以及同号不同使用账户；
22	//   - 账本含未被受理申请（空字段、未知账户、未知会话）的拒绝记录。
23	//
24	// 所有存活请求的计时基准都在 t0；构造终态时临时拨快时钟后再拨回 t0。
25	func backupSetup(t *testing.T) (*Wallet, *clock) {
26		t.Helper()
27		w, c := newTestWallet() // t0 = 2026-01-01 12:00:00 UTC
28		t0 := c.t
29	
30		mustAccount(t, w, "payer", 1000)
31		mustAccount(t, w, "u1", 0)
32		mustAccount(t, w, "u2", 0)
33		if _, err := w.CreateSession("s1", "u1", "dev1", t0.Add(time.Hour)); err != nil {
34			t.Fatal(err)
35		}
36		if _, err := w.CreateSession("s2", "u2", "dev2", t0.Add(time.Hour)); err != nil {
37			t.Fatal(err)
38		}
39		if _, err := w.CreateSession("sa", "payer", "deva", t0.Add(2*time.Hour)); err != nil {
40			t.Fatal(err)
41		}
42		if _, err := w.CreateSession("s3", "u1", "dev3", t0.Add(time.Hour)); err != nil {
43			t.Fatal(err)
44		}
45		if _, err := w.CreateSession("s4", "u2", "dev4", t0.Add(-time.Hour)); err != nil {
46			t.Fatal(err)
47		}
48	
49		mkPolicy := func(id string, threshold int64, wait, reserve time.Duration, per, total int64) PolicySpec {
50			return PolicySpec{
51				ID:                 id,
52				PayerAccountID:     "payer",
53				AllowedAccountIDs:  []string{"u1", "u2"},
54				Operation:          "charge",
55				Payee:              "shop",
56				StartsAt:           t0.Add(-time.Hour),
57				EndsAt:             t0.Add(time.Hour),
58				MaxPerRequest:      per,
59				MaxTotal:           total,
60				ApprovalThreshold:  threshold,
61				ApprovalWait:       wait,
62				MaxReserveDuration: reserve,
63			}
64		}
65		if err := w.SavePolicy(mkPolicy("p-app", 10, 5*time.Minute, 10*time.Hour, 100, 1000)); err != nil {
66			t.Fatal(err)
67		}
68		if err := w.SavePolicy(mkPolicy("p-to", 0, 0, time.Minute, 100, 1000)); err != nil {
69			t.Fatal(err)
70		}
71		if err := w.SavePolicy(mkPolicy("p-notime", 0, 0, 0, 100, 1000)); err != nil {
72			t.Fatal(err)
73		}
74		if err := w.SavePolicy(mkPolicy("p-deact", 0, 0, 0, 100, 1000)); err != nil {
75			t.Fatal(err)
76		}
77		if _, err := w.DeactivatePolicy("p-deact", "sa", "deva", "stop it"); err != nil {
78			t.Fatal(err)
79		}
80		if err := w.RevokeSession("s3"); err != nil {
81			t.Fatal(err)
82		}
83	
84		apply := func(policy, account, sess, dev, rid string, fee int64) RequestView {
85			in := RequestInput{
86				PolicyID: policy, RequestID: rid, AccountID: account, SessionID: sess,
87				DeviceID: dev, Operation: "charge", Payee: "shop", EstimatedFee: fee,
88			}
89			v, err := w.Apply(in)
90			if err != nil {
91				t.Fatalf("apply %s/%s: %v", account, rid, err)
92			}
93			return v
94		}
95	
96		// 直接预留（p-app，费用 5 不超门槛）。
97		apply("p-app", "u1", "s1", "dev1", "direct", 5)
98		// 已结算（实际 3）。
99		apply("p-app", "u1", "s1", "dev1", "settled", 5)
100		if _, err := w.Settle("u1", "settled", 3); err != nil {
101			t.Fatal(err)
102		}
103		// 已预留后取消。
104		apply("p-app", "u1", "s1", "dev1", "cancel-reserved", 5)
105		if _, err := w.Cancel("u1", "cancel-reserved"); err != nil {
106			t.Fatal(err)
107		}
108		// 待审批（恢复时才到期）。
109		apply("p-app", "u1", "s1", "dev1", "pending-due", 20)
110		// 批准后预留。
111		apply("p-app", "u2", "s2", "dev2", "approved", 20)
112		if _, err := w.Approve("u2", "approved", "sa", "deva"); err != nil {
113			t.Fatal(err)
114		}
115		// 审批拒绝。
116		apply("p-app", "u2", "s2", "dev2", "rejected", 20)
117		if _, err := w.Reject("u2", "rejected", "sa", "deva", "no way"); err != nil {
118			t.Fatal(err)
119		}
120		// 待审批取消。
121		apply("p-app", "u2", "s2", "dev2", "cancel-pending", 20)
122		if _, err := w.Cancel("u2", "cancel-pending"); err != nil {
123			t.Fatal(err)
124		}
125		// 待审批等待过期（终态）：临时拨快时钟触发后拨回。
126		apply("p-app", "u2", "s2", "dev2", "pending-expired", 20)
127		c.t = t0.Add(6 * time.Minute)
128		if r, err := w.Request("u2", "pending-expired"); err != nil || r.State != RequestExpired {
129			t.Fatalf("pending-expired state = %v err = %v", r.State, err)
130		}
131		c.t = t0
132		// 预留超时（终态，释放时刻必须是原截止时刻 t0+1m）：拨快触发后拨回。
133		apply("p-to", "u1", "s1", "dev1", "resv-expired", 5)
134		c.t = t0.Add(2 * time.Minute)
135		if r, err := w.Request("u1", "resv-expired"); err != nil || r.State != RequestReservationExpired {
136			t.Fatalf("resv-expired state = %v err = %v", r.State, err)
137		}
138		c.t = t0
139		// 恢复时才到期的预留（截止 t0+1m，导出时仍存活）。
140		apply("p-to", "u1", "s1", "dev1", "resv-due", 5)
141		// 关闭预留超时：很久以后仍等待结算或取消。
142		apply("p-notime", "u1", "s1", "dev1", "no-timeout", 5)
143		// 同号不同使用账户：分别识别。
