340	func policyViewsEqual(a, b PolicyView) bool {
341		// AllowedAccountIDs 由 map 生成，顺序不稳定；按集合比较。
342		aAllowed := append([]string(nil), a.AllowedAccountIDs...)
343		bAllowed := append([]string(nil), b.AllowedAccountIDs...)
344		sort.Strings(aAllowed)
345		sort.Strings(bAllowed)
346		if len(aAllowed) != len(bAllowed) {
347			return false
348		}
349		for i := range aAllowed {
350			if aAllowed[i] != bAllowed[i] {
351				return false
352			}
353		}
354		a.AllowedAccountIDs, b.AllowedAccountIDs = nil, nil
355		// PolicySpec 含切片字段，不能直接用 != 比较；逐字段核对。
356		if a.ID != b.ID || a.PayerAccountID != b.PayerAccountID ||
357			a.Operation != b.Operation || a.Payee != b.Payee ||
358			!a.StartsAt.Equal(b.StartsAt) || !a.EndsAt.Equal(b.EndsAt) ||
359			a.MaxPerRequest != b.MaxPerRequest || a.MaxTotal != b.MaxTotal ||
360			a.ApprovalThreshold != b.ApprovalThreshold || a.ApprovalWait != b.ApprovalWait ||
361			a.MaxReserveDuration != b.MaxReserveDuration {
362			return false
363		}
364		return a.ReservedTotal == b.ReservedTotal && a.SpentTotal == b.SpentTotal &&
365			a.Deactivated == b.Deactivated && a.DeactivatedAt.Equal(b.DeactivatedAt) &&
366			a.DeactivatorAccountID == b.DeactivatorAccountID && a.DeactivateReason == b.DeactivateReason
367	}
368	
369	func requestViewsEqual(a, b RequestView) bool {
370		return a.PolicyID == b.PolicyID && a.RequestID == b.RequestID && a.AccountID == b.AccountID &&
371			a.PayerAccountID == b.PayerAccountID && a.Operation == b.Operation && a.Payee == b.Payee &&
372			a.EstimatedFee == b.EstimatedFee && a.ActualFee == b.ActualFee && a.State == b.State &&
373			a.CreatedAt.Equal(b.CreatedAt) && a.SettledAt.Equal(b.SettledAt) &&
374			a.WaitDeadline.Equal(b.WaitDeadline) && a.ReservedAt.Equal(b.ReservedAt) &&
375			a.ReserveDuration == b.ReserveDuration && a.ReserveDeadline.Equal(b.ReserveDeadline) &&
376			a.ReserveExpiredAt.Equal(b.ReserveExpiredAt) && a.DecidedAt.Equal(b.DecidedAt) &&
377			a.ApproverAccountID == b.ApproverAccountID && a.RejectReason == b.RejectReason
378	}
