615			t.Fatal(err)
616		}
617		w2, err := restoreAt(data, t0)
618		if err != nil {
619			t.Fatal(err)
620		}
621	
622		// 同号同内容重复申请：返回已有结果，不重复预留、不记账。
623		same := RequestInput{
624			PolicyID: "p-app", RequestID: "direct", AccountID: "u1", SessionID: "s1",
625			DeviceID: "dev1", Operation: "charge", Payee: "shop", EstimatedFee: 5,
626		}
627		ledgerBefore := len(w2.Ledger())
628		balBefore, _ := w2.Balance("payer")
629		v, err := w2.Apply(same)
630		if err != nil || v.State != RequestReserved {
631			t.Fatalf("idempotent re-apply: %+v %v", v, err)
632		}
633		if got := len(w2.Ledger()); got != ledgerBefore {
634			t.Fatalf("idempotent re-apply appended ledger: %d -> %d", ledgerBefore, got)
635		}
636		if bal, _ := w2.Balance("payer"); bal != balBefore {
637			t.Fatalf("idempotent re-apply moved money: %+v", bal)
638		}
639		// 同号不同内容：冲突。
640		diff := same
641		diff.EstimatedFee = 4
642		if _, err := w2.Apply(diff); !errors.Is(err, ErrConflict) {
643			t.Fatalf("conflicting re-apply err = %v, want ErrConflict", err)
644		}
645		// 不同使用账户同号：各自识别，互不冲突。
646		other := same
647		other.AccountID, other.SessionID, other.DeviceID, other.EstimatedFee = "u2", "s2", "dev2", 5
648		other.RequestID = "direct"
649		other.PolicyID = "p-notime"
650		if _, err := w2.Apply(other); err != nil {
651			t.Fatalf("same request id under different account: %v", err)
652		}
653	
654		// 重复结算幂等、不同金额冲突；重复取消幂等。
655		if v, err := w2.Settle("u1", "settled", 3); err != nil || v.State != RequestSettled {
656			t.Fatalf("repeat settle: %+v %v", v, err)
657		}
658		if _, err := w2.Settle("u1", "settled", 2); !errors.Is(err, ErrConflict) {
659			t.Fatalf("conflicting settle err = %v", err)
660		}
661		if v, err := w2.Cancel("u1", "cancel-reserved"); err != nil || v.State != RequestCancelled {
662			t.Fatalf("repeat cancel: %+v %v", v, err)
663		}
664	}
