1552			{
1553				id: "p2", per: 100, total: 50,
1554				reqs: []quotaReqSpec{
1555					{id: "s2", account: "u2", estFee: 30, actualFee: 20, state: RequestSettled},
1556					{id: "r2", account: "u2", estFee: 30, state: RequestReserved},
1557				},
1558			},
1559		})
1560		if _, err := restoreAt(data, t0); err != nil {
1561			t.Fatalf("two policies each at their own limit: %v", err)
1562		}
1563	}
1564	
1565	// TestRestoreCumulativeQuotaIgnoresNonOccupyingStates 验证只有现存预留与已
1566	// 结算实际费用占用累计额度：待审批、审批拒绝、待审批取消、待审批过期、已
1567	// 预留后取消、预留超时的请求都不占用；结算退回的差额也不计入已花费。
1568	func TestRestoreCumulativeQuotaIgnoresNonOccupyingStates(t *testing.T) {
1569		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
1570		// 累计上限仅 10：一笔实际费用 10 的已结算请求占满额度；其余请求费用均
1571		// 为 30（待审批系严格超过门槛 10），但都不占用额度，备份仍合法。
1572		data := buildCumulativeQuotaBackup(t, t0, []quotaPolicySpec{{
1573			id: "p-free", per: 100, total: 10, threshold: 10,
1574			wait: 5 * time.Minute, reserveDur: time.Minute,
1575			reqs: []quotaReqSpec{
1576				{id: "settled", account: "u1", estFee: 10, actualFee: 10, state: RequestSettled},
1577				{id: "reserved-cancelled", account: "u1", estFee: 10, state: RequestCancelled, wasReserved: true},
1578				{id: "reservation-expired", account: "u1", estFee: 10, state: RequestReservationExpired},
1579				{id: "pending", account: "u1", estFee: 30, state: RequestPendingApproval},
1580				{id: "rejected", account: "u1", estFee: 30, state: RequestRejected, rejectReason: "no"},
1581				{id: "pending-expired", account: "u1", estFee: 30, state: RequestExpired},
1582				{id: "pending-cancelled", account: "u1", estFee: 30, state: RequestCancelled},
1583			},
1584		}})
1585		w2, err := restoreAt(data, t0)
1586		if err != nil {
1587			t.Fatalf("non-counting states restore: %v", err)
1588		}
1589		// 未到期的待审批请求不被改写；没有任何现存预留，账户预留余额为零。
1590		r, err := w2.Request("u1", "pending")
1591		if err != nil || r.State != RequestPendingApproval {
1592			t.Fatalf("pending request state = %v err = %v, want still pending", r.State, err)
1593		}
1594		if bal, _ := w2.Balance("payer"); bal != (Balances{Available: 0, Reserved: 0}) {
1595			t.Fatalf("payer balance = %+v, want zero reserved", bal)
1596		}
1597	}
1598	
1599	// ---- 并发 ----
1600	
1601	func TestExportConcurrentWithMutations(t *testing.T) {
1602		w, c := newTestWallet()
1603		t0 := c.t
1604		mustAccount(t, w, "payer", 1_000_000)
1605		mustAccount(t, w, "u1", 0)
1606		mustAccount(t, w, "u2", 0)
1607		if _, err := w.CreateSession("s1", "u1", "dev1", t0.Add(24*time.Hour)); err != nil {
1608			t.Fatal(err)
1609		}
1610		if _, err := w.CreateSession("s2", "u2", "dev2", t0.Add(24*time.Hour)); err != nil {
1611			t.Fatal(err)
1612		}
1613		if err := w.SavePolicy(PolicySpec{
1614			ID: "p1", PayerAccountID: "payer", AllowedAccountIDs: []string{"u1", "u2"},
1615			Operation: "charge", Payee: "shop",
1616			StartsAt: t0.Add(-time.Hour), EndsAt: t0.Add(24 * time.Hour),
1617			MaxPerRequest: 100, MaxTotal: 1_000_000,
1618			MaxReserveDuration: time.Hour,
1619		}); err != nil {
1620			t.Fatal(err)
1621		}
1622	
1623		const n = 200
1624		var wg sync.WaitGroup
1625		var backups [][]byte
1626		var mu sync.Mutex
1627	
1628		// 申请/结算/取消/导出 并发；每个备份都必须是可恢复的完整状态。
1629		for g := 0; g < 4; g++ {
1630			g := g
1631			wg.Add(1)
1632			go func() {
1633				defer wg.Done()
1634				for i := 0; i < n; i++ {
1635					rid := fmt.Sprintf("g%d-r%d", g, i)
1636					in := RequestInput{
1637						PolicyID: "p1", RequestID: rid, AccountID: "u2", SessionID: "s2",
1638						DeviceID: "dev2", Operation: "charge", Payee: "shop", EstimatedFee: 1,
1639					}
1640					if _, err := w.Apply(in); err != nil {
1641						t.Errorf("apply: %v", err)
1642						return
1643					}
1644					switch i % 3 {
1645					case 0:
1646						if _, err := w.Settle("u2", rid, 1); err != nil {
1647							t.Errorf("settle: %v", err)
1648						}
1649					case 1:
1650						if _, err := w.Cancel("u2", rid); err != nil {
1651							t.Errorf("cancel: %v", err)
1652						}
1653					}
1654				}
1655			}()
1656		}
1657		wg.Add(1)
1658		go func() {
1659			defer wg.Done()
1660			for i := 0; i < n; i++ {
1661				data, err := w.Export()
1662				if err != nil {
1663					t.Errorf("export: %v", err)
1664					return
1665				}
1666				mu.Lock()
1667				backups = append(backups, data)
1668				mu.Unlock()
1669			}
1670		}()
1671		wg.Wait()
1672	
1673		if len(backups) == 0 {
1674			t.Fatal("no backups captured")
1675		}
1676		for i, data := range backups {
1677			w2, err := Restore(data)
1678			if err != nil {
1679				t.Fatalf("backup %d not restorable: %v", i, err)
1680			}
1681			// 恢复出的钱包余额自洽：非负且预留不凭空消失。
1682			for _, id := range []string{"payer"} {
1683				bal, err := w2.Balance(id)
1684				if err != nil {
1685					t.Fatalf("backup %d balance: %v", i, err)
1686				}
1687				if bal.Available < 0 || bal.Reserved < 0 {
1688					t.Fatalf("backup %d negative balance: %+v", i, bal)
1689				}
1690			}
1691		}
1692	
1693		// 最终状态本身也必须可导出/恢复且账本完整（用与源钱包相同的受控时刻，
1694		// 避免恢复时钟把未到期预留结算掉而混淆比较）。
1695		final, err := w.Export()
1696		if err != nil {
1697			t.Fatal(err)
1698		}
1699		w2, err := restoreAt(final, c.t)
1700		if err != nil {
1701			t.Fatal(err)
1702		}
1703		if l1, l2 := len(w.Ledger()), len(w2.Ledger()); l1 != l2 {
1704			t.Fatalf("final ledger length = %d, want %d", l2, l1)
1705		}
1706	}
1707

