		t.Fatalf("ledger length drift on same-time restore: source %d restored %d", l1, l2)
	}
	b1, _ := w.Balance("payer")
	b2, _ := w2.Balance("payer")
	if b1 != b2 {
		t.Fatalf("balance drift: source %+v restored %+v", b1, b2)
	}
}

