206		}
207		// 一笔已预留：保留原状态与金额。
208		reserved := approvalApply()
209		reserved.RequestID = "r3"
210		reserved.EstimatedFee = 8
211		if _, err := w.Apply(reserved); err != nil {
212			t.Fatal(err)
213		}
