562			w, _ := setupDeactivate(t)
563			if _, err := w.Apply(approvalApply()); err != nil {
564				t.Fatal(err)
565			}
566	
567			var wg sync.WaitGroup
568			wg.Add(2)
569			var approveErr, deactivateErr error
570			go func() { defer wg.Done(); _, approveErr = w.Approve("u1", "r1", "sa", "dev-approve") }()
571			go func() {
572				defer wg.Done()
573				_, deactivateErr = w.DeactivatePolicy("p-approval", "sa", "dev-approve", "concurrent stop")
574			}()
575			wg.Wait()
576	
577			req, _ := w.Request("u1", "r1")
578			pv, _ := w.Policy("p-approval")
579			bal, _ := w.Balance("payer")
580	
581			if approveErr == nil {
582				// 批准先完成：请求已预留并保留预留，随后停用不再处理它。
583				if deactivateErr != nil {
584					t.Fatalf("deactivate after approve should succeed: %v", deactivateErr)
585				}
586				if req.State != RequestReserved {
587					t.Fatalf("iter %d: approve first but state = %v", iter, req.State)
588				}
589				if bal != (Balances{Available: 80, Reserved: 20}) {
590					t.Fatalf("iter %d: balance = %+v, want {80 20}", iter, bal)
591				}
592				// 已预留仍可结算。
593				if _, err := w.Settle("u1", "r1", 20); err != nil {
594					t.Fatalf("iter %d: settle after approve+deactivate: %v", iter, err)
595				}
596			} else {
597				// 停用先完成：请求必须是拒绝终态，不能再批准。
598				if req.State != RequestRejected {
599					t.Fatalf("iter %d: deactivate first but state = %v approveErr=%v", iter, req.State, approveErr)
600				}
601				if !errors.Is(approveErr, ErrRequestNotPending) {
602					t.Fatalf("iter %d: approve after deactivate err = %v, want ErrRequestNotPending", iter, approveErr)
603				}
604				if bal != (Balances{Available: 100, Reserved: 0}) {
605					t.Fatalf("iter %d: balance = %+v, want untouched", iter, bal)
606				}
607			}
608			// 不变量：策略已停用时绝不存在可批准的待审批请求。
609			if pv.Deactivated && req.State == RequestPendingApproval {
610				t.Fatalf("iter %d: deactivated policy still has approvable pending request", iter)
611			}
612			// 停用留痕恰好一条。
613			if countKind(w.Ledger(), LedgerPolicyDeactivation) != 1 {
614				t.Fatalf("iter %d: deactivation entries != 1", iter)
615			}
616		}
617	}
618	
619	func TestConcurrentDeactivateAndApply(t *testing.T) {
620		for iter := 0; iter < 50; iter++ {
621			w, _ := setupDeactivate(t)
622	
623			var wg sync.WaitGroup
624			wg.Add(2)
625			var applyErr, deactivateErr error
626			in := approvalApply() // 费用 20 > 门槛 10，申请成功会进入待审批，不冻结余额
627			go func() { defer wg.Done(); _, applyErr = w.Apply(in) }()
628			go func() {
629				defer wg.Done()
630				_, deactivateErr = w.DeactivatePolicy("p-approval", "sa", "dev-approve", "race stop")
631			}()
632			wg.Wait()
633	
634			if deactivateErr != nil {
635				t.Fatalf("deactivate failed: %v", deactivateErr)
636			}
637			req, _ := w.Request("u1", "r1")
638			if applyErr == nil {
639				// 申请先完成：请求停留审批时被停用立即拒绝（未到期限）。
640				if req.State != RequestRejected {
641					t.Fatalf("iter %d: apply first, want rejected after deactivation, got %v", iter, req.State)
642				}
643			} else {
644				// 停用先完成：新申请被策略已停用拒绝，请求不存在。
645				if !errors.Is(applyErr, ErrPolicyDeactivated) {
646					t.Fatalf("iter %d: apply err = %v, want ErrPolicyDeactivated", iter, applyErr)
647				}
648				if _, err := w.Request("u1", "r1"); !errors.Is(err, ErrRequestNotFound) {
649					t.Fatalf("iter %d: rejected-by-deactivation request should not exist", iter)
650				}
651			}
652			// 待审批与停用拒绝都不冻结余额。
653			if bal, _ := w.Balance("payer"); bal != (Balances{Available: 100, Reserved: 0}) {
654				t.Fatalf("iter %d: balance = %+v, want untouched", iter, bal)
655			}
656			if countKind(w.Ledger(), LedgerPolicyDeactivation) != 1 {
657				t.Fatalf("iter %d: deactivation entries != 1", iter)
658			}
659		}
660	}
661	
662	func TestConcurrentRepeatDeactivation(t *testing.T) {
663		w, _ := setupDeactivate(t)
664		if _, err := w.Apply(approvalApply()); err != nil {
665			t.Fatal(err)
666		}
667	
668		const n = 16
669		var wg sync.WaitGroup
670		wg.Add(n)
671		for i := 0; i < n; i++ {
672			go func() {
673				defer wg.Done()
674				_, _ = w.DeactivatePolicy("p-approval", "sa", "dev-approve", "concurrent stop")
675			}()
676		}
677		wg.Wait()
678	
679		// 并发重复停用只能记录一次；待审批只拒绝一次。
680		if countKind(w.Ledger(), LedgerPolicyDeactivation) != 1 {
681			t.Fatal("deactivation recorded more than once")
682		}
683		if countKind(w.Ledger(), LedgerRejection) != 1 {
684			t.Fatal("pending request rejected more than once")
685		}
686		pv, _ := w.Policy("p-approval")
687		if !pv.Deactivated || pv.DeactivateReason != "concurrent stop" {
688			t.Fatalf("policy view = %+v", pv)
689		}
690		// 余额与累计额度无变动。
691		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 100, Reserved: 0}) {
692			t.Fatalf("balance = %+v", bal)
693		}
694		if pv.ReservedTotal != 0 || pv.SpentTotal != 0 {
695			t.Fatalf("totals changed: %+v", pv)
696		}
697	}
698	
699	func TestDeactivateDistinguishesLedgerKinds(t *testing.T) {
700		w, _ := setupDeactivate(t)
701		if _, err := w.Apply(approvalApply()); err != nil {
702			t.Fatal(err)
703		}
704		if _, err := w.DeactivatePolicy("p-approval", "sa", "dev-approve", "stop"); err != nil {
705			t.Fatal(err)
706		}
707	
708		// 停用与请求拒绝是两类记录：分别关联出资账户+策略、使用账户+请求。
709		var deact, rej int
710		for _, e := range w.Ledger() {
711			switch e.Kind {
712			case LedgerPolicyDeactivation:
713				deact++
714				if e.AccountID != "payer" || e.PolicyID != "p-approval" || e.RequestID != "" || e.Amount != 0 {
715					t.Fatalf("bad deactivation entry: %+v", e)
716				}
717			case LedgerRejection:
718				rej++
719				if e.AccountID != "u1" || e.PolicyID != "" || e.RequestID != "r1" || e.Amount != 0 {
720					t.Fatalf("bad rejection entry: %+v", e)
721				}
722			}
723		}
724		if deact != 1 || rej != 1 {
725			t.Fatalf("deactivation = %d rejection = %d, want 1/1", deact, rej)
726		}
727		// 按账户查询也能核对：出资账户只见停用，使用账户只见拒绝。
728		if countKind(w.AccountLedger("payer"), LedgerPolicyDeactivation) != 1 ||
729			countKind(w.AccountLedger("payer"), LedgerRejection) != 0 {
730			t.Fatalf("payer ledger = %+v", w.AccountLedger("payer"))
731		}
732		if countKind(w.AccountLedger("u1"), LedgerRejection) != 1 ||
733			countKind(w.AccountLedger("u1"), LedgerPolicyDeactivation) != 0 {
734			t.Fatalf("u1 ledger = %+v", w.AccountLedger("u1"))
735		}
736	}
737	
738	func countKind(entries []LedgerEntry, kind LedgerKind) int {
739		n := 0
740		for _, e := range entries {
741			if e.Kind == kind {
742				n++
743			}
744		}
745		return n
746	}
