1	package wallet
2	
3	import (
4		"encoding/json"
5		"errors"
6		"strings"
7		"testing"
8		"time"
9	)
10	
11	// buildExpiredPendingTimingBackup 构造一笔“超门槛待审批、从未预留费用、因等待
12	// 审批到期进入已过期终态”的请求备份，所有计时字段默认合法：提交于 t0、等待
13	// 截止 t0+1h（策略窗口至 t0+24h、会话至 t0+24h，均不抢先）、于 t0+2h 才发现
14	// 并记录过期决定。mutate 在余额核对前调整请求/策略/会话的计时字段，以便构造
15	// 各类不合法历史。
16	func buildExpiredPendingTimingBackup(t *testing.T, t0 time.Time, mutate func(*requestBackupV1, *policyBackupV1, *sessionBackupV1)) []byte {
17		t.Helper()
18		const fee int64 = 20
19		r := requestBackupV1{
20			PolicyID: "p", RequestID: "big", AccountID: "u1", PayerAccountID: "payer",
21			SessionID: "s1", Operation: "charge", Payee: "shop",
22			EstimatedFee: fee,
23			State:        int(RequestExpired),
24			CreatedAt:    timeJSON(t0),
25			WaitDeadline: timeJSON(t0.Add(time.Hour)),
26			DecidedAt:    timeJSON(t0.Add(2 * time.Hour)),
27		}
28		pol := policyBackupV1{
29			ID: "p", PayerAccountID: "payer", AllowedAccountIDs: []string{"u1"},
30			Operation: "charge", Payee: "shop",
31			StartsAt:           timeJSON(t0.Add(-time.Hour)),
32			EndsAt:             timeJSON(t0.Add(24 * time.Hour)),
33			MaxPerRequest:      100,
34			MaxTotal:           1000,
35			ApprovalThreshold:  10,
36			ApprovalWait:       durationJSON(time.Hour),
37			MaxReserveDuration: durationJSON(2 * time.Hour),
38		}
39		sess := sessionBackupV1{
40			ID: "s1", AccountID: "u1", DeviceID: "d1",
41			ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0.Add(-2 * time.Hour)),
42		}
43		if mutate != nil {
44			mutate(&r, &pol, &sess)
45		}
46	
47		b := backupV1{
48			Version:    backupVersion,
49			ExportedAt: timeJSON(t0.Add(-time.Minute)),
50			Accounts: []accountBackupV1{
51				{ID: "payer", Available: 100, Reserved: 0, CreatedAt: timeJSON(t0.Add(-2 * time.Hour))},
52				{ID: "u1", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0.Add(-2 * time.Hour))},
53			},
54			Sessions: []sessionBackupV1{sess},
55			Policies: []policyBackupV1{pol},
56			Requests: []requestBackupV1{r},
57			Ledger: []ledgerEntryBackupV1{
58				{Kind: int(LedgerPendingApproval), AccountID: "u1", RequestID: "big", At: timeJSON(t0)},
59				{Kind: int(LedgerExpiration), AccountID: "u1", RequestID: "big", Reason: "approval period expired", At: timeJSON(t0.Add(2 * time.Hour))},
60			},
61		}
62		data, err := json.Marshal(&b)
63		if err != nil {
64			t.Fatal(err)
65		}
66		return data
67	}
68	
69	// assertExpirationTimingRejected 恢复必须失败、包装 ErrBackupInvalid，并在
70	// 错误信息中点名使用账户与请求编号；不得返回部分恢复的钱包。
71	func assertExpirationTimingRejected(t *testing.T, data []byte, at time.Time) string {
72		t.Helper()
73		w2, err := restoreAt(data, at)
74		if err == nil {
75			if w2 != nil {
76				t.Fatalf("invalid expiration history restored a wallet: %+v", w2)
77			}
78			t.Fatal("invalid expiration history restored without error")
79		}
80		if !errors.Is(err, ErrBackupInvalid) {
81			t.Fatalf("err = %v, want ErrBackupInvalid", err)
82		}
83		msg := err.Error()
84		if !strings.Contains(msg, `"u1"`) || !strings.Contains(msg, `"big"`) {
85			t.Fatalf("error %q must name usage account and request id", msg)
86		}
87		return msg
88	}
89	
90	// TestRestoreExpiredPendingTimingAccepted 验证合法的待审批过期历史照常恢复：
91	// 决定恰在截止时刻、或到期很久后才发现过期均可；即使恢复时会话已到期或被
92	// 吊销、策略已结束或停用，仍保持原过期状态与全部时刻，不追加过期记录、不
93	// 产生资金变动。
94	func TestRestoreExpiredPendingTimingAccepted(t *testing.T) {
95		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
96	
97		t.Run("expired restores long after windows end", func(t *testing.T) {
98			data := buildExpiredPendingTimingBackup(t, t0, nil)
99			w2, err := restoreAt(data, t0.Add(48*time.Hour))
100			if err != nil {
101				t.Fatalf("legal expiration must restore: %v", err)
102			}
103			r, err := w2.Request("u1", "big")
104			if err != nil {
105				t.Fatal(err)
106			}
107			if r.State != RequestExpired {
108				t.Fatalf("state = %v, want expired", r.State)
109			}
110			// 时刻原样保留：决定时刻不得被改写为截止时刻或恢复时的当前时间。
111			if !r.CreatedAt.Equal(t0) || !r.WaitDeadline.Equal(t0.Add(time.Hour)) ||
112				!r.DecidedAt.Equal(t0.Add(2*time.Hour)) {
113				t.Fatalf("timing rewritten: created %v deadline %v decided %v",
114					r.CreatedAt, r.WaitDeadline, r.DecidedAt)
115			}
116			if r.ApproverAccountID != "" || r.RejectReason != "" {
117				t.Fatalf("expired request must not carry approver/reason: %+v", r)
118			}
119			// 终态不改写：不追加任何记录，余额与额度不变。
120			if got := len(w2.Ledger()); got != 2 {
121				t.Fatalf("restore appended ledger entries: got %d entries, want 2", got)
122			}
123			if bal, _ := w2.Balance("payer"); bal != (Balances{Available: 100, Reserved: 0}) {
124				t.Fatalf("payer balance = %+v, want untouched", bal)
125			}
126		})
127	
128		t.Run("decided exactly at deadline restores", func(t *testing.T) {
129			data := buildExpiredPendingTimingBackup(t, t0, func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
130				r.DecidedAt = timeJSON(t0.Add(time.Hour))
131			})
132			if _, err := restoreAt(data, t0.Add(time.Minute)); err != nil {
133				t.Fatalf("expiration exactly at deadline must be legal: %v", err)
134			}
135		})
136	
137		t.Run("decided one nanosecond after deadline restores", func(t *testing.T) {
138			data := buildExpiredPendingTimingBackup(t, t0, func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
139				r.DecidedAt = timeJSON(t0.Add(time.Hour + time.Nanosecond))
140			})
141			if _, err := restoreAt(data, t0.Add(time.Minute)); err != nil {
142				t.Fatalf("expiration 1ns after deadline must be legal: %v", err)
143			}
144		})
145	
146		t.Run("decided long after deadline restores", func(t *testing.T) {
147			// 钱包可能在到期很久后才发现请求过期：决定时刻远晚于截止时刻合法。
148			data := buildExpiredPendingTimingBackup(t, t0, func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
149				r.DecidedAt = timeJSON(t0.Add(30 * 24 * time.Hour))
150			})
151			w2, err := restoreAt(data, t0.Add(60*24*time.Hour))
152			if err != nil {
153				t.Fatalf("late-discovered expiration must restore: %v", err)
154			}
155			r, err := w2.Request("u1", "big")
156			if err != nil {
157				t.Fatal(err)
158			}
159			if !r.DecidedAt.Equal(t0.Add(30 * 24 * time.Hour)) {
160				t.Fatalf("decided_at rewritten to %v", r.DecidedAt)
161			}
162		})
163	
164		t.Run("deadline bounded by policy end", func(t *testing.T) {
165			data := buildExpiredPendingTimingBackup(t, t0, func(r *requestBackupV1, p *policyBackupV1, _ *sessionBackupV1) {
166				p.EndsAt = timeJSON(t0.Add(30 * time.Minute))
167				r.WaitDeadline = timeJSON(t0.Add(30 * time.Minute))
168				r.DecidedAt = timeJSON(t0.Add(40 * time.Minute))
169			})
170			if _, err := restoreAt(data, t0.Add(time.Minute)); err != nil {
171				t.Fatalf("policy-end bounded deadline: %v", err)
172			}
173		})
174	
175		t.Run("deadline bounded by session expiry", func(t *testing.T) {
176			// 任务示例：最长等待允许到 12:10，申请会话 12:05 到期，截止应为
177			// 12:05；12:08 才查询并记录过期决定的历史可以恢复。
178			data := buildExpiredPendingTimingBackup(t, t0, func(r *requestBackupV1, p *policyBackupV1, s *sessionBackupV1) {
179				p.ApprovalWait = durationJSON(10 * time.Minute)
180				s.ExpiresAt = timeJSON(t0.Add(5 * time.Minute))
181				r.WaitDeadline = timeJSON(t0.Add(5 * time.Minute))
182				r.DecidedAt = timeJSON(t0.Add(8 * time.Minute))
183			})
184			w2, err := restoreAt(data, t0.Add(48*time.Hour))
185			if err != nil {
186				t.Fatalf("session-expiry bounded deadline: %v", err)
187			}
188			r, err := w2.Request("u1", "big")
189			if err != nil {
190				t.Fatal(err)
191			}
192			if !r.WaitDeadline.Equal(t0.Add(5*time.Minute)) || !r.DecidedAt.Equal(t0.Add(8*time.Minute)) {
193				t.Fatalf("timing rewritten: deadline %v decided %v", r.WaitDeadline, r.DecidedAt)
194			}
195		})
196	
197		t.Run("session revoked and policy deactivated at restore", func(t *testing.T) {
198			data := buildExpiredPendingTimingBackup(t, t0, func(r *requestBackupV1, p *policyBackupV1, s *sessionBackupV1) {
199				s.Revoked = true
200				p.Deactivated = true
201				p.DeactivatedAt = timeJSON(t0.Add(3 * time.Hour))
202				p.DeactivatorAccountID = "payer"
203				p.DeactivateReason = "no longer needed"
204			})
205			if _, err := restoreAt(data, t0.Add(48*time.Hour)); err != nil {
206				t.Fatalf("legal expiration must restore despite revoked session and deactivated policy: %v", err)
207			}
208		})
209	
210		t.Run("timezone representation does not change outcome", func(t *testing.T) {
211			// 同一时刻的不同时区写法：t0+1h UTC 即该瞬间在 +02:00 的 14:00。
212			data := buildExpiredPendingTimingBackup(t, t0, func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
213				r.WaitDeadline = timeJSON(t0.Add(time.Hour).In(time.FixedZone("UTC+2", 2*3600)))
214				r.DecidedAt = timeJSON(t0.Add(2 * time.Hour).In(time.FixedZone("UTC-5", -5*3600)))
215			})
216			if _, err := restoreAt(data, t0.Add(time.Minute)); err != nil {
217				t.Fatalf("same instant in another zone must restore: %v", err)
218			}
219		})
220	}
221	
222	// TestRestoreRejectsExpiredPendingTiming 验证待审批过期的请求：等待截止缺失、
223	// 被改长/改短（含只按最长等待时长计算而忽略更早的策略结束或会话到期），或
224	// 过期决定早于截止时刻，都必须让整个备份被拒绝——余额与累计金额自洽也不能
225	// 放行。
226	func TestRestoreRejectsExpiredPendingTiming(t *testing.T) {
227		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
228	
229		cases := []struct {
230			name   string
231			mutate func(*requestBackupV1, *policyBackupV1, *sessionBackupV1)
232			reason string
233		}{
234			{
235				name: "missing wait deadline",
236				mutate: func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
237					r.WaitDeadline = timeJSON(time.Time{})
238				},
239				reason: "missing wait deadline",
240			},
241			{
242				name: "lengthened wait deadline",
243				mutate: func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
244					r.WaitDeadline = timeJSON(t0.Add(2 * time.Hour))
245				},
246				reason: "does not match min",
247			},
248			{
249				name: "shortened wait deadline",
250				mutate: func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
251					r.WaitDeadline = timeJSON(t0.Add(15 * time.Minute))
252				},
253				reason: "does not match min",
254			},
255			{
256				name: "deadline moved but still before decision",
257				mutate: func(r *requestBackupV1, p *policyBackupV1, s *sessionBackupV1) {
258					// 任务示例：最长等待允许到 12:10、会话 12:05 到期，正确截止
259					// 为 12:05；改成 12:06 后决定时刻 12:08 仍晚于截止，也必须拒绝。
260					p.ApprovalWait = durationJSON(10 * time.Minute)
261					s.ExpiresAt = timeJSON(t0.Add(5 * time.Minute))
262					r.WaitDeadline = timeJSON(t0.Add(6 * time.Minute))
263					r.DecidedAt = timeJSON(t0.Add(8 * time.Minute))
264				},
265				reason: "does not match min",
266			},
267			{
268				name: "deadline ignores earlier session expiry",
269				mutate: func(r *requestBackupV1, _ *policyBackupV1, s *sessionBackupV1) {
270					s.ExpiresAt = timeJSON(t0.Add(20 * time.Minute))
271					// 正确截止应为 t0+20m，备份仍按最长等待时长保存 t0+1h。
272				},
273				reason: "does not match min",
274			},
275			{
276				name: "deadline ignores earlier policy end",
277				mutate: func(r *requestBackupV1, p *policyBackupV1, _ *sessionBackupV1) {
278					p.EndsAt = timeJSON(t0.Add(30 * time.Minute))
279					// 正确截止应为 t0+30m，备份仍按最长等待时长保存 t0+1h。
280				},
281				reason: "does not match min",
282			},
283			{
284				name: "decision before deadline",
285				mutate: func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
286					r.DecidedAt = timeJSON(t0.Add(time.Hour - time.Nanosecond))
287				},
288				reason: "before wait deadline",
289			},
290			{
291				name: "missing decided_at",
292				mutate: func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
293					r.DecidedAt = timeJSON(time.Time{})
294				},
295				reason: "missing decided_at",
296			},
297		}
298		for _, tc := range cases {
299			t.Run(tc.name, func(t *testing.T) {
300				data := buildExpiredPendingTimingBackup(t, t0, tc.mutate)
301				// 恢复时刻远近都不影响结论：只按备份记载的时间判断。
302				for _, at := range []time.Time{t0.Add(time.Minute), t0.Add(48 * time.Hour)} {
303					msg := assertExpirationTimingRejected(t, data, at)
304					if !strings.Contains(msg, tc.reason) {
305						t.Fatalf("error %q must explain %q", msg, tc.reason)
306					}
307				}
308			})
309		}
310	}
311	
312	// TestRestoreExpiredTimingConsistentBalancesCannotPass 验证余额与策略累计金额
313	// 完全自洽的备份，只要过期时间矛盾仍必须整体拒绝。
314	func TestRestoreExpiredTimingConsistentBalancesCannotPass(t *testing.T) {
315		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
316		data := buildExpiredPendingTimingBackup(t, t0, func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
317			// 截止时刻被清空：余额与累计金额丝毫不受影响，也必须拒绝。
318			r.WaitDeadline = timeJSON(time.Time{})
319		})
320		assertExpirationTimingRejected(t, data, t0.Add(time.Minute))
321	}
322	
323	// TestRestoreReservationExpiredUnaffectedByExpirationTiming 验证已预留费用的
324	// 预留超时不适用待审批过期的时限核对：其等待截止字段本就不存在，仍按既有
325	// 预留超时规则恢复。
326	func TestRestoreReservationExpiredUnaffectedByExpirationTiming(t *testing.T) {
327		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
328		// 未超门槛直接预留（费用 5 ≤ 门槛 10），提交时刻 t0 即完成预留、预留
