17		p.ApprovalWait = time.Minute
18		return p
19	}
20	
21	// setupApproval 构造带审批策略的钱包：出资账户 payer（100），使用账户
22	// u1/u2，会话 s1/s2，以及出资账户绑定审批设备的会话 sa。
23	func setupApproval(t *testing.T) (*Wallet, *clock) {
24		t.Helper()
25		w, c := newTestWallet()
26		mustAccount(t, w, "payer", 100)
27		mustAccount(t, w, "u1", 0)
28		mustAccount(t, w, "u2", 0)
29		if _, err := w.CreateSession("s1", "u1", "dev1", c.t.Add(time.Minute)); err != nil {
30			t.Fatal(err)
31		}
32		if _, err := w.CreateSession("s2", "u2", "dev2", c.t.Add(time.Minute)); err != nil {
33			t.Fatal(err)
34		}
35		if _, err := w.CreateSession("sa", "payer", "dev-approve", c.t.Add(time.Hour)); err != nil {
36			t.Fatal(err)
37		}
38		if err := w.SavePolicy(approvalPolicy(c)); err != nil {
39			t.Fatal(err)
40		}
41		return w, c
42	}
43	
44	func approvalApply() RequestInput {
45		return RequestInput{
46			PolicyID:     "p-approval",
47			RequestID:    "r1",
48			AccountID:    "u1",
49			SessionID:    "s1",
50			DeviceID:     "dev1",
51			Operation:    "charge",
52			Payee:        "shop",
53			EstimatedFee: 20,
54		}
55	}
56	
57	func TestSaveApprovalPolicyValidation(t *testing.T) {
58		w, c := newTestWallet()
59		mustAccount(t, w, "payer", 100)
60		mustAccount(t, w, "u1", 0)
61		mustAccount(t, w, "u2", 0)
62	
63		good := approvalPolicy(c)
64		if err := w.SavePolicy(good); err != nil {
65			t.Fatal(err)
66		}
67		// 视图能读回审批配置。
68		pv, err := w.Policy("p-approval")
69		if err != nil {
70			t.Fatal(err)
71		}
72		if pv.ApprovalThreshold != 10 || pv.ApprovalWait != time.Minute {
73			t.Fatalf("approval config = threshold %d wait %v", pv.ApprovalThreshold, pv.ApprovalWait)
74		}
75	
76		cases := []struct {
77			name   string
78			mutate func(*PolicySpec)
79		}{
80			{"negative threshold", func(p *PolicySpec) { p.ApprovalThreshold = -1 }},
